// Parse the response and prepare data
const response = $input.first().json;

// The response should be an array of alert objects
const alerts = Array.isArray(response) ? response : [];

console.log(`Received ${alerts.length} alerts from Supabase`);

if (alerts.length === 0) {
  console.log('No alerts found - all inventory is healthy!');
  return [];
}

// Return each alert as a separate item
return alerts.map(alert => ({ json: alert }));

// Group alerts by sales representative
const items = $input.all();

if (items.length === 0) {
  console.log('No alerts to group');
  return [];
}

const groupedByRep = {};

for (const item of items) {
  const data = item.json;
  const repEmail = data.representative_email;
  const repName = data.representative_name;

  if (!repEmail || repEmail === '') {
    console.log('Skipping alert with no rep email:', data.store_number);
    continue;
  }

  if (!groupedByRep[repEmail]) {
    groupedByRep[repEmail] = {
      representative_email: repEmail,
      representative_name: repName,
      critical_count: 0,
      warning_count: 0,
      alerts: []
    };
  }

  // Count alerts by severity
  if (data.is_critical) {
    groupedByRep[repEmail].critical_count++;
  } else if (data.is_warning) {
    groupedByRep[repEmail].warning_count++;
  }

  // Add alert details
  groupedByRep[repEmail].alerts.push({
    saq_code: data.saq_code,
    product_name: data.product_name,
    format: data.format || 'N/A',
    category: data.category || 'N/A',
    store_number: data.store_number,
    store_name: data.store_name,
    store_city: data.store_city,
    store_region: data.store_region,
    qty_inventory: data.qty_inventory,
    avg_weekly_sales: data.avg_weekly_sales,
    days_of_inventory: data.days_of_inventory,
    is_critical: data.is_critical,
    is_warning: data.is_warning,
    snapshot_date: data.snapshot_date
  });
}

// Convert to array for output
const output = Object.values(groupedByRep);

console.log(`Grouped ${items.length} alerts for ${output.length} sales representatives`);

return output.map(rep => ({ json: rep }));
